// Carry forward the original trigger data alongside the AI config, since the
// next node (Google Calendar) needs tenant date range + calendar id together.
const trigger = $('When Executed by Another Workflow').first().json;
const config = $json;
return [{
  json: {
    tenant_id: trigger.tenant_id,
    date_range_start: trigger.date_range_start,
    date_range_end: trigger.date_range_end,
    business_hours: config.business_hours,
    timezone: config.timezone || 'UTC',
    google_calendar_id: config.google_calendar_id || 'primary',
    // 0042: every calendar to look at (agents' own, else the agency's).
    calendar_ids: (() => {
      let ids = config.calendar_ids;
      if (typeof ids === 'string') { try { ids = JSON.parse(ids); } catch (e) { ids = []; } }
      ids = (Array.isArray(ids) ? ids : []).map(String).filter(Boolean);
      return ids.length ? ids : [config.google_calendar_id || 'primary'];
    })(),
    // 0037: slot length and notice (Elliot's own 15/30-minute calls); viewings keep 60 and none.
    duration_minutes: Number(trigger.duration_minutes) > 0 ? Number(trigger.duration_minutes) : 60,
    // 0038: the agency's own notice and buffer (Settings → Viewings); a caller's notice wins.
    min_notice_minutes: Number(trigger.min_notice_minutes) > 0 ? Number(trigger.min_notice_minutes)
      : (Number(config.booking_notice_minutes) > 0 ? Number(config.booking_notice_minutes) : 0),
    buffer_minutes: Number(config.booking_buffer_minutes) > 0 ? Number(config.booking_buffer_minutes) : 0
  }
}];

